def transform(grid):
    h, w = len(grid), len(grid[0])
    solid_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    solid_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}
    return [[2 if r in solid_rows or c in solid_cols else grid[r][c]
             for c in range(w)] for r in range(h)]
